<?php

namespace App\Services;

use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use Throwable;

/**
 * Reusable service for storing / deleting files on Cloudflare R2.
 *
 * The R2 bucket is private — files can only be accessed through
 * time-limited signed URLs generated by signedUrl().
 *
 * Usage:
 *   $path = app(R2StorageService::class)->upload($file, 'thumbnails');
 *   $url  = app(R2StorageService::class)->signedUrl($path);
 *   app(R2StorageService::class)->delete($path);
 */
class R2StorageService
{
    protected string $disk = 'r2';

    /**
     * Upload a file to R2.
     *
     * @param  UploadedFile  $file    The uploaded file
     * @param  string        $folder  Folder within the bucket (e.g. "thumbnails")
     * @param  string|null   $name    Optional filename (without extension). Auto-generated if null.
     * @return array{path:string, filename:string, disk:string, size:int, mime:string|null}
     */
    public function upload(UploadedFile $file, string $folder = '', ?string $name = null): array
    {
        $folder   = trim($folder, '/');
        $extension = strtolower($file->getClientOriginalExtension() ?: 'bin');
        $filename  = ($name ?: $this->generateUniqueName()) . '.' . $extension;
        $path      = ($folder !== '' ? $folder . '/' : '') . $filename;

        Storage::disk($this->disk)->put(
            $path,
            file_get_contents($file->getRealPath()),
            ['visibility' => 'private', 'ContentType' => $file->getMimeType()]
        );

        return [
            'path'     => $path,
            'filename' => $filename,
            'disk'     => $this->disk,
            'size'     => $file->getSize() ?: 0,
            'mime'     => $file->getMimeType(),
        ];
    }

    /**
     * Stream a local file resource to R2 (memory-efficient for large files).
     *
     * @param  resource  $resource
     */
    public function putStream(string $path, $resource, ?string $mime = null): bool
    {
        $options = ['visibility' => 'private'];
        if ($mime) {
            $options['ContentType'] = $mime;
        }

        return (bool) Storage::disk($this->disk)->put($path, $resource, $options);
    }

    /**
     * Store raw contents at a specific path.
     */
    public function putContents(string $path, string $contents, ?string $mime = null): bool
    {
        $options = ['visibility' => 'private'];
        if ($mime) {
            $options['ContentType'] = $mime;
        }

        return Storage::disk($this->disk)->put($path, $contents, $options);
    }

    /**
     * Delete a file from R2.
     */
    public function delete(?string $path): bool
    {
        if (! $path) {
            return false;
        }

        try {
            if (Storage::disk($this->disk)->exists($path)) {
                return Storage::disk($this->disk)->delete($path);
            }
        } catch (Throwable $e) {
            // Swallow — deletion errors shouldn't break the caller
        }

        return false;
    }

    /**
     * Recursively delete every object inside a "folder" prefix on R2.
     * Used to clean up the old UUID directory when a video is replaced.
     */
    public function deleteDirectory(?string $directory): bool
    {
        if (! $directory || trim($directory, '/') === '') {
            return false;
        }

        $dir = trim($directory, '/');

        try {
            $result = Storage::disk($this->disk)->deleteDirectory($dir);

            \Illuminate\Support\Facades\Log::info('[R2] deleteDirectory', [
                'directory' => $dir,
                'result'    => $result,
            ]);

            return $result;
        } catch (Throwable $e) {
            \Illuminate\Support\Facades\Log::error('[R2] deleteDirectory failed', [
                'directory' => $dir,
                'error'     => $e->getMessage(),
            ]);

            return false;
        }
    }

    /**
     * Generate a short-lived signed URL for a private object.
     *
     * @param  string  $path     Object path inside the bucket
     * @param  int|null $minutes TTL in minutes. Defaults to R2_SIGNED_URL_TTL env.
     */
    public function signedUrl(?string $path, ?int $minutes = null): ?string
    {
        if (! $path) {
            return null;
        }

        $minutes = $minutes ?? (int) env('R2_SIGNED_URL_TTL', 60);
        $minutes = max(1, $minutes);

        try {
            return Storage::disk($this->disk)->temporaryUrl($path, now()->addMinutes($minutes));
        } catch (Throwable $e) {
            return null;
        }
    }

    /**
     * Check whether a file exists on R2.
     */
    public function exists(?string $path): bool
    {
        if (! $path) {
            return false;
        }

        try {
            return Storage::disk($this->disk)->exists($path);
        } catch (Throwable $e) {
            return false;
        }
    }

    /**
     * Unique filename using microtime + random — avoids collisions
     * even when several uploads happen in the same second.
     */
    protected function generateUniqueName(): string
    {
        // e.g. 20260418153012_7f3a9b2c  (timestamp + 8-char random)
        return now()->format('YmdHis') . '_' . Str::lower(Str::random(8));
    }
}
